2397:   /* ===== 资金池分配（修复「排序第一吸干全部资金」）=====
2398:    * 旧逻辑 want = min(capRoom, indRoom, mktRoom, left) —— left 是总剩余，
2399:    * 排序第一的标的会吃满全部增量资金，导致另一市场抢不到钱，沪深配比失效。
2400:    * 新逻辑：先按 sh_ratio 切沪深两个资金池，再在市场内按权重微积分分配。
2401:    * 市场池剩余不足时，允许向另一市场借用「未被使用」的额度（仅当对侧无候选）。 */
2402:   const pool = { '沪': amount * shW, '深': amount * (1 - shW) };
2403:   const poolUsed = { '沪': 0, '深': 0 };
2404:   const otherMkt = m => (m === '沪' ? '深' : '沪');
2405:   cands.forEach(r => {
2406:     if (items.length >= maxBuys) { skipped.push({ r: r, why: '本次已达 ' + maxBuys + ' 只上限（省佣金）' }); return; }
2407:     if (mktBuyCount[r.mkt] >= perMktCapOf(r.mkt)) { skipped.push({ r: r, why: r.mkt + '市本次配额已满' }); return; }
2408:     const capRoom = r.capPct / 100 * base - r.mv;
2409:     const indRoom = maxI / 100 * base - (indUsed[r.ind] || 0);
2410:     const mktRoom = (r.mkt === '沪' ? shW : 1 - shW) * base - (mktUsed[r.mkt] || 0);
2411:     // ① 本市场资金池剩余（增量口径）
2412:     let poolLeft = pool[r.mkt] - poolUsed[r.mkt];
2413:     // ② 若本市场已无候选可买，可借用对侧未用的池（避免现金白白闲置）
2414:     const otherHasCandidate = cands.some(x => x.mkt === otherMkt(r.mkt) && mktBuyCount[x.mkt] < perMktCapOf(x.mkt));
2415:     if (!otherHasCandidate) poolLeft += (pool[otherMkt(r.mkt)] - poolUsed[otherMkt(r.mkt)]);
2416:     // ③ 本次单只预算：均分投入额，而不是按目标权重切分。
2417:     //    理由：月投 1 万买 2 只 → 每只 5000；若按 w% 分（平安 13.52% → 1352 元），
2418:     //    远低于 min_ticket，会被 5 元最低佣金吃掉，也不符合实盘下单习惯。
2419:     //    同时受「本次最多买几只」与「单笔下限」共同约束。
2420:     const plannedCount = Math.max(1, Math.min(maxBuys, cands.length));
2421:     const equalAmt = amount / plannedCount;
2422:     const hardCap = Math.min(capRoom, indRoom, mktRoom, poolLeft);
2423:     const frac = (r.planScore && r.planScore.sizeFrac > 0 && r.planScore.sizeFrac < 1) ? r.planScore.sizeFrac : 1;
2424:     let want = Math.min(equalAmt * frac, hardCap);
2425:     // ④ 满仓不不单笔下限时抬到 min_ticket；半仓不抬，避免把「提前建仓」又买成满仓
2426:     if (want < minTicket) {
2427:       if (frac >= 1 && hardCap >= minTicket) want = minTicket;
2428:       else {
2429:         skipped.push({ r: r, why: (frac < 1 ? '提前建仓（半仓）' : '额度') + '不足单笔下限（可用 ' + fmt(Math.max(0, want), 0) + ' 元 < ' + fmt(minTicket, 0) + '）' });
2430:         return;
2431:       }
2432:     }
2433:     const lotCost = r.price * lot;
2434:     if (want > 0 && want < lotCost && hardCap >= lotCost) want = lotCost;   // 不够 1 手→抬到 1 手
2435:     if (want <= 0) { skipped.push({ r: r, why: '额度已满' }); return; }
2436:     const sh = Math.floor(want / r.price / lot) * lot;
2437:     if (sh <= 0) { skipped.push({ r: r, why: '额度不足 1 手（' + fmt(lotCost, 0) + ' 元）' }); return; }
2438:     const cost = sh * r.price;
2439:     const fee = Math.max(cost * (+S.settings.comm || 0), minFee) + cost * (+S.settings.trans || 0);
2440:     // ⑤ 摩擦硬门槛：单笔成交额必须 ≥ min_ticket，否则不买（5 元最低佣金占比过高）
2441:     if (cost < minTicket) {
2442:       skipped.push({ r: r, why: '单笔 ' + fmt(cost, 0) + ' 元 < 下限 ' + fmt(minTicket, 0) + '，不买' });
2443:       return;
2444:     }
2445:     // 最后一道硬约束：买入后单票 >25% 或单行业 >35%，标红跳过，资金不占用。
2446:     const baseCap = (typeof capitalBase === 'function' ? capitalBase(T) : 0) || base;
2447:     const singleAfter = baseCap > 0 ? (r.mv + cost) / baseCap * 100 : 0;
2448:     const indAfter = baseCap > 0 ? ((indUsed[r.ind] || 0) + cost) / baseCap * 100 : 0;
2449:     if (singleAfter > maxS + 1e-6 || indAfter > maxI + 1e-6) {
2450:       const which = singleAfter > maxS + 1e-6
2451:         ? ('单票 ' + fmt(singleAfter, 1) + '% > ' + maxS + '%')
2452:         : (r.ind + ' ' + fmt(indAfter, 1) + '% > ' + maxI + '%');
2453:       skipped.push({ r: r, why: '超限跳过：买入后' + which, overLimit: true });
2454:       return;
2455:     }
2456:     items.push({ r: r, shares: sh, cost: cost, fee: fee, lowTicket: false, early: frac < 1, score: r.planScore });
2457:     left -= cost;
2458:     poolUsed[r.mkt] += cost;
2459:     mktBuyCount[r.mkt] = (mktBuyCount[r.mkt] || 0) + 1;
2460:     indUsed[r.ind] = (indUsed[r.ind] || 0) + cost;
2461:     mktUsed[r.mkt] = (mktUsed[r.mkt] || 0) + cost;
2462:   });
