tool_input.new_string:
L.push('');
L.push('【4】逐只判定（配置权重 ≠ 本次买入）');
const rows = rowsNow();
const inEl = document.getElementById('inPlanAmount');
const iv = inEl ? parseFloat(inEl.value) : NaN;
const amount = (isFinite(iv) && iv > 0) ? iv : PLAN_AMOUNT_DEFAULT;
const plan = buildPlan(amount, rows, totals(rows));
const actionOf = {};
plan.items.forEach(x => { actionOf[x.r.code] = '买入'; });
plan.skipped.forEach(x => { if (!actionOf[x.r.code]) actionOf[x.r.code] = '不买'; });
const weighted = rows.filter(r => r.w > 0 && r.t);
L.push('  targets ' + TARGETS.length + ' 只，其中 w>0 进入判定 ' + weighted.length + ' 只');
const idle = TARGETS.filter(t => !(+t.w > 0)).map(t => (t.name || t.code) + '(w=' + (t.w || 0) + ')');
L.push('  未进入判定（w=0，不占本次买入）: ' + (idle.length ? idle.join('、') : '无'));
weighted.forEach(r => {
  const m = r.margin;
  const bits = [];
  bits.push('本次动作=' + (actionOf[r.code] === '买入' ? '买入' : '持有不买'));
  bits.push('价=' + (r.price != null ? fmt(r.price, 2) : '无行情'));
  bits.push('w=' + r.w + '%（配置权重，不是本次下单）');
  const mp = getMarginParams(r.t);
  bits.push('行业=' + (r.t.ind || '—') + '[' + (mp.group || '全局') + ']');
  bits.push('参数=' + (mp.targetYldMode || 'dynamic') + (mp.targetYldFixed != null ? ' ' + mp.targetYldFixed + '%' : '') +
    '/垫' + mp.yldPadPct + '/底' + mp.targetYldFloor);
  const rf = indRiskFlags(r.t);
  if (rf.length) bits.push('✗行业红线:' + rf.join('、'));
  if (!m) bits.push('✗缺指标');
  else {
    bits.push('目标股息率=' + fmt(m.targetYld, 2) + '%(' + (m.targetYldConst || '') + ')');
    bits.push('目标价=' + (m.targetBuyAbsolute != null ? fmt(m.targetBuyAbsolute, 2) : '—'));
    bits.push('marginBuy=' + (r.marginBuy ? '✓' : '✗') + '（仅现价≤目标价）');
    // 价格分对所有有指标的标的同一套，不因 marginBuy 或是否在名单里而换口径
    const sc = planScore(r);
    const prem = sc.premium != null ? fmt(Math.max(0, sc.premium), 1) + '%' : '无';
    bits.push('价格分=' + sc.pxPts + '(溢价' + prem + ') 总分=' + sc.total + '(基本面' + sc.fund + '+价格' + sc.price + ')');
  }
  if (r.dpsMissing) bits.push('✗缺dps');
  if (r.fundBreak) bits.push('✗基本面越线');
  const why = (plan.skipped.find(x => x.r.code === r.code) || {}).why;
  if (actionOf[r.code] !== '买入' && why) bits.push('排除=' + why);
  L.push('  ' + r.name + '(' + r.code + ') ' + bits.join(' | '));
});

L.push('');
L.push('【5】本次投入与结果');
L.push('  控件值 = ' + (isFinite(iv) ? iv : '(空/无效)'));
L.push('  实际按 ' + amount + ' 元计算');
