plan.items.forEach(x => L.push('    ✓ ' + x.r.name + ' ' + x.shares + '股 = ' + fmt(x.cost, 0) + ' 元'));
plan.skipped.forEach(x => L.push('    ✗ ' + x.r.name + '：' + x.why));

